from pyspark.sql import functions as F

EXPECTED = ["auth-service", "catalog-api", "checkout-api", "iot-gateway", "notification-worker", "search-api"]
MAX_SILENCE_S = 60


def freshness(application_logs, check_at):
    # One row per expected service: when it last logged, how long ago, and whether that's fresh.
    check_time = F.lit(check_at).cast("timestamp")
    return application_logs.groupBy("service").agg(F.max("logged_at").alias("last_log"))


def solve(application_logs):
    return freshness(application_logs, "2026-04-14 10:01:25")
